import React, { useState, useEffect } from "react";
import { useParams } from "react-router-dom";
import { ImagePlus, Search } from "lucide-react";

export default function PostAttributesPage() {
  const { category } = useParams();

  // Form State
  const [formData, setFormData] = useState({
    title: "",
    description: "",
    price: "",
    category: category || "Vehicles",
    location: "",
    images: [],
    brand: "",
    name: "Lawal Muazu",
    phoneNumber: "",
    contactMethod: [],
  });

  // Update category when URL parameter changes
  useEffect(() => {
    setFormData((prevData) => ({ ...prevData, category: category || "Vehicles" }));
  }, [category]);

  // Handle input changes
  const handleInputChange = (e) => {
    const { name, value } = e.target;
    setFormData({ ...formData, [name]: value });
  };

  // Handle image upload
  const handleImageUpload = (e) => {
    const files = Array.from(e.target.files);
    setFormData((prevData) => ({ ...prevData, images: files }));
  };

  // Form submission
  const handleSubmit = (e) => {
    e.preventDefault();
    alert("Form submitted successfully!");
    console.log(formData); // For debugging
  };

  return (
    <div className="container mx-auto px-4 py-6">
      {/* Header Section */}
      <div className="mb-6 text-center">
        <h1 className="text-2xl font-semibold text-gray-800">POST YOUR AD</h1>
      </div>

      {/* Form Section */}
      <form
        onSubmit={handleSubmit}
        className="bg-white shadow-md rounded-md p-6 space-y-6 max-w-3xl mx-auto"
      >
        {/* Category */}
        <div>
          <label className="block text-gray-700 font-medium mb-1">Category</label>
          <div className="flex items-center justify-between border border-gray-300 rounded-md p-4 bg-gray-50">
            <div className="flex items-center space-x-2">
              <span className="p-2 bg-red-100 rounded-md text-red-500">
                {/* Example Lucide Icon */}
                <ImagePlus className="w-6 h-6" />
              </span>
              <div>
                <p className="font-medium text-gray-800">{formData.category}</p>
                <p className="text-sm text-gray-500">Cars for Sale</p>
              </div>
            </div>
            <button
              type="button"
              className="text-red-500 font-medium hover:underline"
              onClick={() => alert("Change category clicked")}
            >
              Change
            </button>
          </div>
        </div>

        {/* Upload Images */}
        <div>
          <label className="block text-gray-700 font-medium mb-1">Upload Images</label>
          <div className="grid grid-cols-4 gap-2">
            {Array.from({ length: 12 }).map((_, index) => (
              <div
                key={index}
                className="border border-gray-300 rounded-md flex items-center justify-center h-20 cursor-pointer"
              >
                <ImagePlus className="w-6 h-6 text-gray-400" />
              </div>
            ))}
          </div>
          <p className="mt-2 text-sm text-gray-500">
            For the cover picture we recommend using the landscape mode.
          </p>
        </div>

        {/* Brand Selector */}
        <div>
          <label htmlFor="brand" className="block text-gray-700 font-medium mb-1">
            Brand*
          </label>
          <div className="flex items-center border border-gray-300 rounded-md p-2 bg-gray-50">
            <Search className="w-5 h-5 text-gray-500" />
            <input
              type="text"
              id="brand"
              name="brand"
              value={formData.brand}
              onChange={handleInputChange}
              placeholder="Select brand"
              className="w-full bg-transparent outline-none px-2 text-gray-700"
            />
          </div>
        </div>

        {/* Ad Title */}
        <div>
          <label htmlFor="title" className="block text-gray-700 font-medium mb-1">
            Ad Title*
          </label>
          <input
            type="text"
            id="title"
            name="title"
            value={formData.title}
            onChange={handleInputChange}
            className="block w-full border border-gray-300 rounded-md p-2"
            placeholder="Mention the key features of your item (e.g. brand, model, age, type)"
          />
          <p className="mt-1 text-sm text-gray-500 text-right">1/70</p>
        </div>

        {/* Description */}
        <div>
          <label htmlFor="description" className="block text-gray-700 font-medium mb-1">
            Description*
          </label>
          <textarea
            id="description"
            name="description"
            value={formData.description}
            onChange={handleInputChange}
            className="block w-full border border-gray-300 rounded-md p-2"
            placeholder="Describe the item you’re selling"
          />
          <p className="mt-1 text-sm text-gray-500 text-right">0/4096</p>
        </div>

        {/* Submit Button */}
        <div>
          <button
            type="submit"
            className="w-full bg-red-500 text-white py-2 px-4 rounded-md shadow-sm hover:bg-red-600"
          >
            Post Now
          </button>
        </div>
      </form>
    </div>
  );
}
